// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around AdhocEventBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// AdhocEventEntityI.
func (c *AdhocEventColumns) Marshal(w io.Writer) (err error) {
	ent := adhocEventPool.Get().(*cbdml.InEntityFacts)
	defer adhocEventPool.Put(ent)
	ent.SetActiveSections(AdhocEventActiveSections)
	ent.Builder().SetActiveFields(AdhocEventActiveFields())
	err = AdhocEventBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("adhocevent: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("adhocevent: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// adhocEventReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type adhocEventReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	Symbol          *ra.ReadAccessFactsTaggedSymbol
	StringArray     *ra.ReadAccessFactsTaggedStringArray
	U64Array        *ra.ReadAccessFactsTaggedU64Array
}

func newAdhocEventReader() *adhocEventReader {
	return &adhocEventReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		Symbol:          ra.NewReadAccessFactsTaggedSymbol(),
		StringArray:     ra.NewReadAccessFactsTaggedStringArray(),
		U64Array:        ra.NewReadAccessFactsTaggedU64Array(),
	}
}

func (r *adhocEventReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocevent: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocevent: load EntityTimestamp: %w", err)
		return
	}
	err = r.Symbol.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocevent: load Symbol: %w", err)
		return
	}
	err = r.StringArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocevent: load StringArray: %w", err)
		return
	}
	err = r.U64Array.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocevent: load U64Array: %w", err)
		return
	}
	return
}

func (r *adhocEventReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.Symbol != nil {
		r.Symbol.Release()
	}
	if r.StringArray != nil {
		r.StringArray.Release()
	}
	if r.U64Array != nil {
		r.U64Array.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around AdhocEventFillFromArrow — the per-row decode lives there.
func (c *AdhocEventColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newAdhocEventReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = AdhocEventFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.Symbol.Attributes, r.Symbol.Memberships,
		r.StringArray.Attributes, r.StringArray.Memberships,
		r.U64Array.Attributes, r.U64Array.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// AdhocEventCodec is the buscodec.CodecI bridge for AdhocEvent. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type AdhocEventCodec struct{}

var _ buscodec.CodecI = (*AdhocEventCodec)(nil)

// adhocEventBusCodec is the package-local singleton wired into buscodec.
var adhocEventBusCodec = &AdhocEventCodec{}

func (inst *AdhocEventCodec) Name() (n string) {
	n = "adhocEvent-sparse-cbor"
	return
}

func (inst *AdhocEventCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=adhocEvent"
	return
}

func (inst *AdhocEventCodec) Encode(v any) (b []byte, err error) {
	var row AdhocEvent
	switch x := v.(type) {
	case AdhocEvent:
		row = x
	case *AdhocEvent:
		if x == nil {
			err = eh.Errorf("adhocevent: Encode nil *AdhocEvent")
			return
		}
		row = *x
	default:
		err = eh.Errorf("adhocevent: Encode requires AdhocEvent or *AdhocEvent, got %T", v)
		return
	}
	cols := &AdhocEventColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("adhocevent: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *AdhocEventCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*AdhocEvent)
	if !ok {
		err = eh.Errorf("adhocevent: Decode requires *AdhocEvent, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("adhocevent: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("adhocevent: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("adhocevent: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &AdhocEventColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("adhocevent: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("adhocevent: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
